//! The identities of the RFC 9963 legacy client authentication tests of
//! the crates without the core test helpers, generated at run time: an
//! ECDSA P-256 CA and `localhost` server certificate (rcgen), and a client
//! certificate from that CA for an RSA-2048 key generated by
//! `browntls_crypto::rsa`. The client's key is loaded with
//! `crypto::native::sign::any_rsa_pkcs1_legacy_type`, so that it signs with
//! RSASSA-PKCS1-v1_5 only. Nothing secret is committed.
//!
//! The including crate root names the library as `tls` (`browntls_core`
//! or the facade `browntls`), so that the items are reached the way that
//! crate's tests reach them.

#![allow(
    dead_code,
    unreachable_pub,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic
)]

use std::sync::{Arc, Mutex, OnceLock};

use browntls_crypto::rand::OsRng;
use browntls_crypto::rsa::{MAX_PKCS8_PRIVATE_KEY_DER_LEN, RsaPrivateKey};
use rcgen::{
    BasicConstraints, CertificateParams, DnType, ExtendedKeyUsagePurpose, IsCa, Issuer, KeyPair,
    KeyUsagePurpose,
};

use crate::tls::client::WebPkiServerVerifier;
use crate::tls::client::danger::{HandshakeSignatureValid, ServerCertVerified, ServerCertVerifier};
use crate::tls::crypto::CryptoProvider;
use crate::tls::crypto::native;
use crate::tls::pki_types::{
    CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, ServerName, UnixTime,
};
use crate::tls::server::WebPkiClientVerifier;
use crate::tls::server::danger::{ClientCertVerified, ClientCertVerifier};
use crate::tls::sign::{CertifiedKey, SigningKey};
use crate::tls::version::TLS13;
use crate::tls::{
    ClientConfig, DigitallySignedStruct, DistinguishedName, Error, RootCertStore, ServerConfig,
    SignatureScheme,
};

/// The legacy schemes as an opted-in CertificateRequest lists them.
pub const OPT_IN_ORDER: [SignatureScheme; 3] = [
    SignatureScheme::RSA_PKCS1_SHA512_LEGACY,
    SignatureScheme::RSA_PKCS1_SHA384_LEGACY,
    SignatureScheme::RSA_PKCS1_SHA256_LEGACY,
];

/// The certificates and keys of both sides.
#[derive(Debug)]
pub struct Pki {
    pub ca: CertificateDer<'static>,
    pub server_chain: Vec<CertificateDer<'static>>,
    server_key: Vec<u8>,
    /// The RSA client's end entity and the CA.
    pub client_chain: Vec<CertificateDer<'static>>,
    client_key: Vec<u8>,
}

/// The PKI of this test binary, generated once: RSA key generation is
/// slow.
pub fn pki() -> &'static Pki {
    static PKI: OnceLock<Pki> = OnceLock::new();
    PKI.get_or_init(Pki::new)
}

impl Pki {
    fn new() -> Self {
        let ca_key = KeyPair::generate_for(&rcgen::PKCS_ECDSA_P256_SHA256).unwrap();
        let mut ca_params = CertificateParams::new(Vec::<String>::new()).unwrap();
        ca_params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
        ca_params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];
        ca_params
            .distinguished_name
            .push(DnType::CommonName, "browntls legacy RSA test CA");
        let ca_cert = ca_params.self_signed(&ca_key).unwrap();
        let issuer = Issuer::new(ca_params, ca_key);
        let ca = CertificateDer::from(ca_cert.der().to_vec());

        let end_entity = |key: &KeyPair, name: &str, purpose| {
            let names = match purpose {
                ExtendedKeyUsagePurpose::ServerAuth => vec![name.to_string()],
                _ => Vec::new(),
            };
            let mut params = CertificateParams::new(names).unwrap();
            params.is_ca = IsCa::NoCa;
            params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
            params.extended_key_usages = vec![purpose];
            params.distinguished_name.push(DnType::CommonName, name);
            let cert = params.signed_by(key, &issuer).unwrap();
            vec![CertificateDer::from(cert.der().to_vec()), ca.clone()]
        };

        let server_key = KeyPair::generate_for(&rcgen::PKCS_ECDSA_P256_SHA256).unwrap();
        let server_chain = end_entity(
            &server_key,
            "localhost",
            ExtendedKeyUsagePurpose::ServerAuth,
        );

        let rsa = RsaPrivateKey::generate(2048, &OsRng).unwrap();
        let mut client_key = vec![0; MAX_PKCS8_PRIVATE_KEY_DER_LEN];
        let len = rsa.to_pkcs8_der(&mut client_key).unwrap();
        client_key.truncate(len);
        let rsa_pair = KeyPair::try_from(client_key.as_slice()).unwrap();
        let client_chain = end_entity(
            &rsa_pair,
            "client.example",
            ExtendedKeyUsagePurpose::ClientAuth,
        );

        Self {
            ca,
            server_chain,
            server_key: server_key.serialize_der(),
            client_chain,
            client_key,
        }
    }

    pub fn server_key(&self) -> PrivateKeyDer<'static> {
        PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(self.server_key.clone()))
    }

    pub fn client_key(&self) -> PrivateKeyDer<'static> {
        PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(self.client_key.clone()))
    }

    /// The client's key, signing with RSASSA-PKCS1-v1_5 only.
    pub fn legacy_key(&self) -> Arc<dyn SigningKey> {
        native::sign::any_rsa_pkcs1_legacy_type(&self.client_key()).unwrap()
    }

    pub fn roots(&self) -> Arc<RootCertStore> {
        let mut roots = RootCertStore::empty();
        roots.add(self.ca.clone()).unwrap();
        Arc::new(roots)
    }

    /// The library's server verifier for the CA (default provider),
    /// recording the scheme of each server signature.
    pub fn server_verifier(&self) -> Arc<Recorder<WebPkiServerVerifier>> {
        let inner = WebPkiServerVerifier::builder_with_provider(self.roots(), provider())
            .build()
            .unwrap();
        Recorder::new(inner)
    }

    /// The library's client verifier for the CA (client authentication
    /// mandatory), built with the opt-in table if `opted_in`, recording
    /// the scheme of each client signature.
    pub fn client_verifier(&self, opted_in: bool) -> Arc<Recorder<dyn ClientCertVerifier>> {
        let provider = if opted_in { opt_in() } else { provider() };
        let inner: Arc<dyn ClientCertVerifier> =
            WebPkiClientVerifier::builder_with_provider(self.roots(), provider)
                .build()
                .unwrap();
        assert_eq!(
            OPT_IN_ORDER
                .iter()
                .all(|s| inner.supported_verify_schemes().contains(s)),
            opted_in
        );
        Recorder::new(inner)
    }

    /// A TLS 1.3 client verifying through `verifier` and authenticating
    /// with the legacy key.
    pub fn client_config(&self, verifier: &Arc<Recorder<WebPkiServerVerifier>>) -> ClientConfig {
        ClientConfig::builder_with_provider(provider())
            .with_protocol_versions(&[&TLS13])
            .unwrap()
            .dangerous()
            .with_custom_certificate_verifier(verifier.clone())
            .with_client_auth_certified_key(CertifiedKey::new(
                self.client_chain.clone(),
                self.legacy_key(),
            ))
    }

    /// A TLS 1.3 server authenticating clients through `verifier`.
    pub fn server_config(&self, verifier: &Arc<Recorder<dyn ClientCertVerifier>>) -> ServerConfig {
        ServerConfig::builder_with_provider(provider())
            .with_protocol_versions(&[&TLS13])
            .unwrap()
            .with_client_cert_verifier(verifier.clone())
            .with_single_cert(self.server_chain.clone(), self.server_key())
            .unwrap()
    }
}

/// The native provider as it comes: no legacy scheme.
pub fn provider() -> Arc<CryptoProvider> {
    Arc::new(native::default_provider())
}

/// The native provider with the opt-in table as
/// `signature_verification_algorithms`.
pub fn opt_in() -> Arc<CryptoProvider> {
    let mut provider = native::default_provider();
    provider.signature_verification_algorithms = native::SUPPORTED_SIG_ALGS_WITH_RSA_PKCS1_LEGACY;
    Arc::new(provider)
}

pub fn localhost() -> ServerName<'static> {
    ServerName::try_from("localhost").unwrap()
}

/// Wraps a verifier, recording the scheme of every handshake signature it
/// checks.
#[derive(Debug)]
pub struct Recorder<V: ?Sized> {
    inner: Arc<V>,
    seen: Mutex<Vec<SignatureScheme>>,
}

impl<V: ?Sized> Recorder<V> {
    pub fn new(inner: Arc<V>) -> Arc<Self> {
        Arc::new(Self {
            inner,
            seen: Mutex::default(),
        })
    }

    pub fn seen(&self) -> Vec<SignatureScheme> {
        self.seen.lock().unwrap().clone()
    }

    fn record(&self, dss: &DigitallySignedStruct) {
        self.seen.lock().unwrap().push(dss.scheme);
    }
}

impl ServerCertVerifier for Recorder<WebPkiServerVerifier> {
    fn verify_server_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        intermediates: &[CertificateDer<'_>],
        server_name: &ServerName<'_>,
        ocsp_response: &[u8],
        now: UnixTime,
    ) -> Result<ServerCertVerified, Error> {
        self.inner
            .verify_server_cert(end_entity, intermediates, server_name, ocsp_response, now)
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, Error> {
        self.record(dss);
        self.inner.verify_tls12_signature(message, cert, dss)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, Error> {
        self.record(dss);
        self.inner.verify_tls13_signature(message, cert, dss)
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.inner.supported_verify_schemes()
    }
}

impl ClientCertVerifier for Recorder<dyn ClientCertVerifier> {
    fn client_auth_mandatory(&self) -> bool {
        self.inner.client_auth_mandatory()
    }

    fn root_hint_subjects(&self) -> &[DistinguishedName] {
        self.inner.root_hint_subjects()
    }

    fn verify_client_cert(
        &self,
        end_entity: &CertificateDer<'_>,
        intermediates: &[CertificateDer<'_>],
        now: UnixTime,
    ) -> Result<ClientCertVerified, Error> {
        self.inner
            .verify_client_cert(end_entity, intermediates, now)
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, Error> {
        self.record(dss);
        self.inner.verify_tls12_signature(message, cert, dss)
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> Result<HandshakeSignatureValid, Error> {
        self.record(dss);
        self.inner.verify_tls13_signature(message, cert, dss)
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.inner.supported_verify_schemes()
    }
}
